using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class RedbridgeWharf : LayoutBase
{
    public RedbridgeWharf()
    {
        Name = LayoutNamesEnums.RedbridgeWharf;
        Owner = "Winchester Railway Modellers";
        Description = "Redbridge Wharf is based on the area of Redbridge in Hampshire, where the River Test meets Southampton Water. The station opened in 1847 with the Southampton and Dorchester Railway and became a junction in 1865 when the 'Sprat and Winkle' line opened to Romsey and Andover. The large area of drained marshland between the wharf and the station was used as a material holding area, and later became the sleeper works, manufacturing sleepers, bridge timbers and cast track components; in the final years of operation the site was used to assemble long welded rail sections and set out large pointwork complexes. The focus of the layout is the wharf, with the works behind it and Redbridge station and junction to the rear. On the layout can be seen numerous piles of timber sleepers and a barge, the river itself with its salt marshes, mudflats and causeway, the timber pond, and the foundry and associated buildings connected with track building. The new rail causeway, the absence of the last road bridge and the laying of the third rail set 1965 as the earliest possible operating date, giving flexibility from late steam through to modern image.";
    }
}
